    for name,num in sorted(hosts.items()):
        if name.endswith('.'+zone):
            content=Path(f'pc{num}.startup').read_text()
            ip=re.search(r'inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/24',content).group(1)
            lines.append(f'{name}. IN A {ip}')
    for domain,target in sorted(mx.items()):
        if domain == zone or domain.endswith('.'+zone): lines.append(f'{domain}. IN MX 10 {target}.')
    (base/f'db.{zone}').write_text('\\n'.join(lines)+'\\n')
(base/'named.conf').write_text('\\n'.join(conf)+'\\n')
